public final class GoetiaPortTests {
 private static FakePlayer player(GameTestHelper h){var p=FakePlayerFactory.get(h.getLevel(),new GameProfile(UUID.randomUUID(),"GoetiaTest"));p.setGameMode(GameType.SURVIVAL);var at=h.absolutePos(new BlockPos(3,2,3));p.setPos(at.getX()+.5,at.getY(),at.getZ()+.5);p.getInventory().clearContent();p.getPersistentData().remove("goetia");return p;}
 @GameTest(template="port_empty9",timeoutTicks=80) public static void alignmentAndDeathKeepReleasedRules(GameTestHelper h){var p=player(h);h.assertTrue(GoetiaPlayer.lean(p)==GoetiaPlayer.Alignment.ANGEL&&GoetiaPlayer.alignment(p)==GoetiaPlayer.Alignment.HUMAN,"zero alignment leans angel");GoetiaPlayer.set(p,"impurity",2000);GoetiaPlayer.set(p,"purity",1000);h.assertTrue(GoetiaPlayer.alignment(p)==GoetiaPlayer.Alignment.ANGEL&&GoetiaPlayer.lean(p)==GoetiaPlayer.Alignment.DEMON,"purity wins full alignment, impurity wins lean");GoetiaPlayer.data(p).putBoolean("locked",true);GoetiaPlayer.add(p,"impurity",4,false);h.assertTrue(GoetiaPlayer.data(p).getInt("impurity")==2000,"lock blocks ordinary add");GoetiaPlayer.add(p,"impurity",4,true);h.assertTrue(GoetiaPlayer.data(p).getInt("impurity")==2004,"regardless bypasses lock");GoetiaPlayer.learn(p,"impSymbol");var next=player(h);GoetiaPlayer.cloneDeath(p,next);h.assertTrue(GoetiaPlayer.data(next).getInt("impurity")==2004&&GoetiaPlayer.data(next).getInt("purity")==0&&!GoetiaPlayer.data(next).getBoolean("locked")&&GoetiaPlayer.knowledge(next).contains("impSymbol"),"death retains only impurity and knowledge");h.succeed();}
 @GameTest(template="port_empty9",timeoutTicks=80) public static void spellThresholdsAndFlightQuirk(GameTestHelper h){var p=player(h);h.assertTrue(GoetiaSpells.ALL.size()==13,"all thirteen released spells");h.assertTrue(GoetiaSpells.ALL.get(0).cost()==30&&java.util.Arrays.equals(GoetiaSpells.ALL.get(0).shape(),new int[]{1,6,3,4}),"burning touch gesture and threshold");p.setItemInHand(InteractionHand.MAIN_HAND,new ItemStack(GoetiaContent.item("soul_focus")));GoetiaPlayer.set(p,"impurity",29);h.assertTrue(!GoetiaSpells.cast(p,"burningTouch"),"below threshold refused");GoetiaPlayer.set(p,"impurity",30);h.assertTrue(GoetiaSpells.cast(p,"burningTouch")&&GoetiaPlayer.data(p).getInt("burning_touch")==600&&GoetiaPlayer.data(p).getInt("impurity")==30,"cast does not spend alignment");GoetiaPlayer.set(p,"impurity",196);h.assertTrue(GoetiaSpells.cast(p,"ebonWings")&&p.getAbilities().mayfly,"wings grant flight");for(int i=0;i<1800;i++)GoetiaPlayer.tick(p);h.assertTrue(!GoetiaPlayer.data(p).contains("wings_tag")&&p.getAbilities().mayfly,"released flight remains after visual timer expires");h.succeed();}
 @GameTest(template="port_empty9",timeoutTicks=80) public static void symbolNeedsExtraXpAndCharges101Ticks(GameTestHelper h){var p=player(h);var s=GoetiaEntities.SYMBOLS.get(0).get().create(h.getLevel());var at=h.absolutePos(new BlockPos(3,2,3));for(int x=-1;x<=1;x++)for(int z=-1;z<=1;z++)h.getLevel().setBlockAndUpdate(at.offset(x,-1,z),Blocks.STONE.defaultBlockState());s.setPos(at.getX()+.5,at.getY(),at.getZ()+.5);s.setNoAi(true);s.setNoGravity(true);p.experienceLevel=5;h.assertTrue(!s.activate(p),"equal XP cost is refused");p.experienceLevel=6;h.assertTrue(s.activate(p)&&p.experienceLevel==1,"one extra XP level activates");for(int i=0;i<100;i++)s.tick();h.assertTrue(s.ready()<1,"float charge still below one after100");s.tick();h.assertTrue(s.ready()>1&&s.fade()<1,"101st charge completes and starts fade same tick");var imps=h.getLevel().getEntitiesOfClass(GoetiaDemon.class,s.getBoundingBox().inflate(2),e->e.kind==0);h.assertTrue(imps.size()==1,"one imp summoned");for(var d:imps)d.discard();s.discard();h.succeed();}
 @GameTest(template="port_empty9",timeoutTicks=80) public static void forgeConsumesWholeStackAndAllDemons(GameTestHelper h){var w=h.getLevel();var s=GoetiaEntities.SYMBOLS.get(4).get().create(w);var at=h.absolutePos(new BlockPos(3,3,3));s.setPos(at.getX()+.5,at.getY(),at.getZ()+.5);var ds=new java.util.ArrayList<GoetiaDemon>();for(int i=0;i<3;i++){var d=GoetiaEntities.DEMONS.get(2).get().create(w);d.setPos(s.getX()+i,s.getY(),s.getZ());d.setNoAi(true);w.addFreshEntity(d);ds.add(d);}var input=new ItemEntity(w,s.getX(),s.getY()+1,s.getZ(),new ItemStack(GoetiaContent.item("demon_horn"),4));w.addFreshEntity(input);h.assertTrue(s.forge(),"three demons always exceed value45");h.assertTrue(input.isRemoved()&&ds.stream().allMatch(GoetiaDemon::isRemoved),"entire input stack and all demons removed");var results=w.getEntitiesOfClass(ItemEntity.class,s.getBoundingBox().inflate(3),e->GoetiaContent.is(e.getItem(),"demon_horn_spear"));h.assertTrue(results.size()==1&&results.get(0).getItem().getCount()==1,"one spear result");for(var e:results)e.discard();h.succeed();}
 @GameTest(template="port_empty9",timeoutTicks=80) public static void cleanseWinsOverBloodSummoning(GameTestHelper h){var w=h.getLevel();var p=player(h);var at=h.absolutePos(new BlockPos(3,2,3));w.setBlockAndUpdate(at,GoetiaContent.block("altar").defaultBlockState());w.setBlockAndUpdate(at.above(),GoetiaContent.block("full_bowl").defaultBlockState());var bowl=(GoetiaBlockData)w.getBlockEntity(at.above());bowl.entity="minecraft:cow";w.setBlockAndUpdate(at.above().north(),GoetiaContent.block("angel_candle_stand").defaultBlockState());w.setBlockAndUpdate(at.above().south(),GoetiaContent.block("demon_candle_stand").defaultBlockState());GoetiaPlayer.set(p,"impurity",500);GoetiaPlayer.data(p).putBoolean("locked",true);h.assertTrue(GoetiaRituals.perform(w,at,p),"cleanse matches");h.assertTrue(GoetiaPlayer.data(p).getInt("impurity")==0&&GoetiaPlayer.data(p).getBoolean("locked")&&w.getBlockState(at.above()).is(GoetiaContent.block("full_bowl")),"cleanse resets alignment but leaves lock and bowl");w.removeBlock(at.above().north(),false);h.assertTrue(GoetiaRituals.perform(w,at,p)&&w.getBlockState(at.above()).is(GoetiaContent.block("empty_bowl")),"blood summon consumes bowl contents");h.succeed();}
 @GameTest(template="port_empty9",timeoutTicks=80) public static void demonsAndHolyWaterKeepTheirAttributes(GameTestHelper h){for(int i=0;i<3;i++){var d=GoetiaEntities.DEMONS.get(i).get().create(h.getLevel());h.assertTrue(d.getMaxHealth()==new float[]{28,52,92}[i]&&d.fireImmune(),"released demon health and fire immunity");d.holyWater();h.assertTrue(!d.fireImmune()&&d.isOnFire(),"holy water disables immunity before fire");d.trap();var tag=new net.minecraft.nbt.CompoundTag();d.addAdditionalSaveData(tag);var copy=GoetiaEntities.DEMONS.get(i).get().create(h.getLevel());copy.readAdditionalSaveData(tag);h.assertTrue(copy.trapped(),"trap state saves");}h.succeed();}
 @GameTest(template="port_empty9",timeoutTicks=80) public static void voraciousDamageRunsAfterCooldownAndBeforeArmor(GameTestHelper h){var p=player(h);var cow=EntityType.COW.create(h.getLevel());cow.setPos(p.getX(),p.getY(),p.getZ()+2);cow.setNoAi(true);GoetiaPlayer.data(p).putInt("voracious_strikes",300);cow.hurt(p.damageSources().playerAttack(p),8);h.assertTrue(Math.abs(cow.getHealth()-(cow.getMaxHealth()-2))<.01&&cow.invulnerableTime==0,"voracious final damage2 and invulnerability0; health="+cow.getHealth()+" invulnerability="+cow.invulnerableTime);cow.setHealth(cow.getMaxHealth());GoetiaPlayer.data(p).putInt("inner_fire_grace",2400);cow.hurt(p.damageSources().playerAttack(p),8);h.assertTrue(Math.abs(cow.getHealth()-(cow.getMaxHealth()-2.8f))<.01&&cow.invulnerableTime==0,"combined voracious and inner damage2.8");h.succeed();}
 @GameTest(template="port_empty9",timeoutTicks=80) public static void innerFireDoesNotChangeCooldownSelection(GameTestHelper h){var p=player(h);var cow=EntityType.COW.create(h.getLevel());cow.setNoAi(true);cow.getAttribute(net.minecraft.world.entity.ai.attributes.Attributes.MAX_HEALTH).setBaseValue(40);cow.setHealth(40);cow.hurt(p.damageSources().playerAttack(p),10);float after=cow.getHealth();h.assertTrue(cow.isAlive()&&Math.abs(after-30)<.01&&cow.invulnerableTime>10,"first hit establishes a live cooldown window");GoetiaPlayer.data(p).putInt("inner_fire_grace",2400);boolean accepted=cow.hurt(p.damageSources().playerAttack(p),8);h.assertTrue(!accepted&&cow.getHealth()==after,"smaller raw hit is rejected before inner multiplier");cow.invulnerableTime=0;cow.hurt(p.damageSources().playerAttack(p),8);h.assertTrue(Math.abs(cow.getHealth()-(after-11.2f))<.01,"accepted hit gets1.4 multiplier before armor");h.succeed();}

 @GameTest(template="port_empty9",timeoutTicks=80) public static void fireballKeepsFixedLegacyAcceleration(GameTestHelper h){
  var p=player(h);var w=h.getLevel();var at=h.absolutePos(new BlockPos(3,6,3));var dir=new net.minecraft.world.phys.Vec3(1,.25,.4);
  var f=new net.minecraft.world.entity.projectile.LargeFireball(w,p,dir.x,dir.y,dir.z,1);f.setOwner(null);f.setPos(at.getX()+.5,at.getY(),at.getZ()+.5);GoetiaFireballs.start(f,dir);h.assertTrue(f.getOwner()==null,"released shot starts without owner");
  var expected=f.position();var velocity=net.minecraft.world.phys.Vec3.ZERO;var power=GoetiaFireballs.normalize(dir).scale(.1);
  for(int i=0;i<5;i++){expected=expected.add(velocity);velocity=velocity.add(power).scale((double).95F);f.tick();h.assertTrue(f.position().distanceTo(expected)<1e-8&&f.getDeltaMovement().distanceTo(velocity)<1e-8,"legacy position/acceleration tick"+i);}
  f.setDeltaMovement(0,.2,0);var expectedOffAxis=new net.minecraft.world.phys.Vec3(0,.2,0).add(power).scale((double).95F);f.tick();h.assertTrue(f.getDeltaMovement().distanceTo(expectedOffAxis)<1e-8,"acceleration stays fixed after off-axis motion");
  var saved=new net.minecraft.nbt.CompoundTag();f.addAdditionalSaveData(saved);var copy=EntityType.FIREBALL.create(w);copy.readAdditionalSaveData(saved);h.assertTrue(((LegacyFireballFlight)copy).goetia$power().distanceTo(power)<1e-8&&copy.getOwner()==null,"fixed acceleration saves without retaining an owner");
  boolean punch=f.hurt(p.damageSources().playerAttack(p),1);h.assertTrue(punch&&f.getDeltaMovement().distanceTo(p.getLookAngle())<1e-8&&f.getOwner()==p,"punch redirects velocity and ownership: accepted="+punch+" actual="+f.getDeltaMovement()+" expected="+p.getLookAngle()+" owner="+f.getOwner());
  p.attack(f);h.assertTrue(f.getDeltaMovement().distanceTo(p.getLookAngle())<1e-8&&((LegacyFireballFlight)f).goetia$power().distanceTo(p.getLookAngle().scale(.1))<1e-8,"actual player attack resets fixed power");var vanilla=EntityType.FIREBALL.create(w);h.assertTrue(!((LegacyFireballFlight)vanilla).goetia$hasFlight(),"ordinary fireballs are outside adapter");h.succeed();
 }
 @GameTest(template="port_empty9",timeoutTicks=80) public static void bloodKnifeProducesOneTypedBottle(GameTestHelper h){
  var p=player(h);p.setItemInHand(InteractionHand.MAIN_HAND,new ItemStack(GoetiaContent.item("blood_knife")));p.getInventory().setItem(1,new ItemStack(Items.GLASS_BOTTLE,2));var cow=EntityType.COW.create(h.getLevel());cow.setNoAi(true);cow.hurt(p.damageSources().playerAttack(p),100);
  int blood=0,glass=0;for(var stack:p.getInventory().items){if(stack.is(Items.GLASS_BOTTLE))glass+=stack.getCount();if(GoetiaContent.is(stack,"liquid_bottle")){blood+=stack.getCount();h.assertTrue(GoetiaItem.tag(stack).getString("entityName").equals("minecraft:cow"),"blood stores killed entity");}}
  h.assertTrue(blood==1&&glass==1,"one kill consumes one bottle and produces one blood");h.succeed();
 }
@GameTest(template="port_empty9", timeoutTicks=80)
public static void holyWaterUsesRealWaterAndBreathingPaths(GameTestHelper h) {
 var w=h.getLevel();
 for(int x=2;x<=4;x++)for(int z=2;z<=4;z++){
  w.setBlockAndUpdate(h.absolutePos(new BlockPos(x,0,z)),Blocks.STONE.defaultBlockState());
  for(int y=1;y<=4;y++)w.setBlockAndUpdate(h.absolutePos(new BlockPos(x,y,z)),GoetiaFluids.BLOCK.get().defaultBlockState());
 }
 var a=h.absolutePos(new BlockPos(3,2,3));
 var cow=EntityType.COW.create(w);cow.setNoAi(true);cow.setNoGravity(true);cow.setPos(a.getX()+.5,a.getY(),a.getZ()+.5);
 cow.setAirSupply(100);cow.setSecondsOnFire(10);cow.fallDistance=17;
 cow.baseTick();
 h.assertTrue(cow.isInWater()&&cow.isInWaterOrRain(),"holy water preserves material-water wet queries");
 h.assertTrue(cow.getFluidHeight(net.minecraft.tags.FluidTags.WATER)>0,"water-height query includes custom fluid");
 h.assertTrue(cow.isEyeInFluid(net.minecraft.tags.FluidTags.WATER),"water eye query includes custom fluid");
 h.assertTrue(cow.getAirSupply()<100,"ordinary land mob uses actual engine breathing consumption");
 h.assertTrue(cow.getRemainingFireTicks()<=0&&cow.fallDistance==0,"actual entity water update extinguishes and resets falls");
 cow.addEffect(new net.minecraft.world.effect.MobEffectInstance(net.minecraft.world.effect.MobEffects.WATER_BREATHING,100));
 cow.setAirSupply(100);cow.baseTick();h.assertTrue(cow.getAirSupply()==100,"water-breathing effect prevents consumption");
 var squid=EntityType.SQUID.create(w);squid.setNoAi(true);squid.setNoGravity(true);squid.setPos(a.getX()+.5,a.getY(),a.getZ()+.5);squid.setAirSupply(100);squid.baseTick();
 h.assertTrue(squid.canBreatheUnderwater()&&squid.getAirSupply()>=100,"water-breathing mob exemption survives custom FluidType");
 h.succeed();
}


 private static final class TickProbe extends FakePlayer {
  int timerAtMovement;net.minecraft.world.phys.Vec3 motionAtMovement;
  TickProbe(net.minecraft.server.level.ServerLevel level){super(level,new GameProfile(UUID.randomUUID(),"TickProbe"));}
  @Override public void aiStep(){timerAtMovement=GoetiaPlayer.data(this).getInt("inner_fire_grace");motionAtMovement=getDeltaMovement();}
 }
 @GameTest(template="port_empty9",timeoutTicks=80) public static void effectTicksBeforeMovementExactlyOnce(GameTestHelper h){var p=new TickProbe(h.getLevel());var at=h.absolutePos(new BlockPos(3,3,3));p.setPos(at.getX(),at.getY(),at.getZ());p.setOnGround(true);p.setDeltaMovement(.2,0,.3);GoetiaPlayer.data(p).putInt("inner_fire_grace",2);p.doTick();h.assertTrue(p.timerAtMovement==1&&Math.abs(p.motionAtMovement.x-.28)<1e-8&&Math.abs(p.motionAtMovement.z-.42)<1e-8,"timer and1.4 motion apply once before movement");p.setOnGround(true);p.setDeltaMovement(.2,0,.3);p.doTick();h.assertTrue(p.timerAtMovement==0&&Math.abs(p.motionAtMovement.x-.2)<1e-8,"expired timer is removed before movement");h.succeed();}
 @GameTest(template="port_empty9",timeoutTicks=80) public static void alignmentThresholdIsCapturedPerPlayer(GameTestHelper h){int saved=GoetiaConfig.THRESHOLD.get();try{GoetiaConfig.THRESHOLD.set(1000);var old=player(h);GoetiaPlayer.set(old,"impurity",750);GoetiaConfig.THRESHOLD.set(500);var fresh=player(h);GoetiaPlayer.set(fresh,"impurity",750);h.assertTrue(GoetiaPlayer.alignment(old)==GoetiaPlayer.Alignment.HUMAN&&GoetiaPlayer.alignment(fresh)==GoetiaPlayer.Alignment.DEMON,"existing player retains captured threshold while new player captures reload");}finally{GoetiaConfig.THRESHOLD.set(saved);}h.succeed();}

 
}
